import { randomUUID } from "node:crypto";
import {
	mkdirSync,
	readFileSync,
	writeFileSync,
	existsSync,
	appendFileSync,
} from "node:fs";
import { resolve, dirname } from "node:path";
import { parseArgs } from "node:util";
import { hash } from "../../eval/seed/corpus.ts";
import { asRecord } from "../../src/index.ts";
import { openTestStore } from "../../test/support/sqlite-store.ts";
import { MODEL, withLuna, type LunaResult } from "../seed-luna/luna.ts";
import {
	extractionInstructions,
	extractionSchema,
} from "../multi-source-comparison/protocol.ts";
import {
	extractionPrompt,
	interpret,
	persist,
	contexts,
	type AnswerContext,
} from "../multi-source-comparison/world.ts";
import {
	packets,
	questions,
	VERSION,
	type SourceQuestion,
	regressions,
} from "./fixtures.ts";
import {
	arms,
	instructions,
	design,
	presentation,
	schemaFor,
	order,
} from "./protocol.ts";
import { assess, summarize, type Cell } from "./results.ts";

const { values } = parseArgs({
	options: {
		resume: { type: "string" },
		"prepare-only": { type: "boolean", default: false },
	},
	strict: true,
});
const root = resolve(import.meta.dir, "../..");
const output = values.resume
	? resolve(values.resume)
	: resolve(
			root,
			"artifacts/instruction-order-factorial",
			`${new Date().toISOString().replaceAll(":", "-")}-${randomUUID().slice(0, 8)}`,
		);
mkdirSync(resolve(output, "cache"), { recursive: true });
console.log(`Run: ${output}`);
const codePaths: string[] = [];
for (const folder of [
	"src",
	"examples/linked-answer-holdout",
	"examples/operative-sources-comparison",
	"examples/operative-sources-holdout",
	"examples/applicability-order-comparison",
	"examples/instruction-order-factorial",
	"examples/multi-source-comparison",
	"examples/seed-luna",
])
	for await (const file of new Bun.Glob("**/*.{ts,json}").scan({
		cwd: resolve(root, folder),
	}))
		codePaths.push(`${folder}/${file}`);
codePaths.push(
	"eval/seed/corpus.ts",
	"test/support/sqlite-store.ts",
	"test/eval/instruction-order-factorial.test.ts",
	"package.json",
	"bun.lock",
);
codePaths.sort();
const digests = Object.fromEntries(
	codePaths.map((f) => [f, hash(readFileSync(resolve(root, f)))]),
);
const protocol = {
	version: VERSION,
	model: MODEL,
	reasoningEffort: "medium",
	samplingSeed: null,
	temperature: null,
	runtime: { bun: Bun.version, sdk: "0.163.0" },
	packets,
	questions,
	regressions,
	arms,
	instructions,
	extractionInstructions,
	extractionSchema,
	design,
	codeDigests: digests,
};
const protocolText = JSON.stringify(protocol, null, 2);
const protoPath = resolve(output, "protocol.json");
if (values.resume) {
	if (readFileSync(protoPath, "utf8") !== protocolText)
		throw new Error("frozen_protocol_changed");
} else {
	writeFileSync(protoPath, protocolText, { flag: "wx" });
	for (const f of codePaths) {
		const dest = resolve(output, "frozen-code", f);
		mkdirSync(dirname(dest), { recursive: true });
		writeFileSync(dest, readFileSync(resolve(root, f)), { flag: "wx" });
	}
}
const cells: Cell[] = [];
const extractionCosts: {
	packetId: string;
	status: string;
	inputTokens?: number;
	outputTokens?: number;
	latencyMs?: number;
	error?: string;
}[] = [];
const report = {
	version: VERSION,
	status: "prepared",
	protocolDigest: hash(Buffer.from(protocolText)),
	cells,
	extractionCosts,
	summary: summarize(cells, questions),
	codeUnchanged: true,
};
function checkpoint() {
	cells.sort(
		(a, b) =>
			a.repeat - b.repeat ||
			a.questionId.localeCompare(b.questionId) ||
			a.arm.localeCompare(b.arm),
	);
	report.summary = summarize(cells, questions);
	writeFileSync(
		resolve(output, "report.json"),
		JSON.stringify(report, null, 2),
	);
}
type Run = (prompt: string, schema: unknown) => Promise<LunaResult>;
let newCalls = 0;
let reused = 0;
async function call(key: string, prompt: string, schema: unknown, run: Run) {
	const file = resolve(output, "cache", `${key}.json`);
	const failure = resolve(output, "cache", `${key}-failure.json`);
	const requestDigest = hash(Buffer.from(JSON.stringify({ prompt, schema })));
	if (existsSync(failure))
		throw new Error(JSON.parse(readFileSync(failure, "utf8")).error as string);
	if (existsSync(file)) {
		const v = asRecord(JSON.parse(readFileSync(file, "utf8")));
		const response = asRecord(v?.["response"]);
		const usage = asRecord(response?.["usage"]);
		if (
			v?.["requestDigest"] !== requestDigest ||
			typeof v?.["latencyMs"] !== "number" ||
			typeof response?.["raw"] !== "string" ||
			typeof usage?.["input_tokens"] !== "number" ||
			typeof usage?.["output_tokens"] !== "number"
		)
			throw new Error("invalid_cache");
		reused++;
		return {
			raw: response["raw"],
			inputTokens: usage["input_tokens"],
			outputTokens: usage["output_tokens"],
			latencyMs: v["latencyMs"],
		};
	}
	writeFileSync(
		resolve(output, "cache", `${key}-request.json`),
		JSON.stringify({ prompt, schema, requestDigest }, null, 2),
	);
	const event = (event: string, error?: string) =>
		appendFileSync(
			resolve(output, "events.jsonl"),
			JSON.stringify({
				key,
				event,
				at: new Date().toISOString(),
				...(error ? { error } : {}),
			}) + "\n",
		);
	event("started");
	const start = performance.now();
	newCalls++;
	try {
		const response = await run(prompt, schema);
		if (!response.usage) throw new Error("usage_missing");
		const latencyMs = performance.now() - start;
		writeFileSync(
			file,
			JSON.stringify({ requestDigest, response, latencyMs }, null, 2),
			{ flag: "wx" },
		);
		event("completed");
		return {
			raw: response.raw,
			inputTokens: response.usage.input_tokens,
			outputTokens: response.usage.output_tokens,
			latencyMs,
		};
	} catch (e) {
		const error = e instanceof Error ? e.message : String(e);
		writeFileSync(failure, JSON.stringify({ requestDigest, error }), {
			flag: "wx",
		});
		event("failed", error);
		throw e;
	}
}
interface Prepared {
	question: SourceQuestion;
	context: AnswerContext;
	history: ReturnType<typeof persist>;
}
const prepared: Prepared[] = regressions.map((c) => ({ ...c, history: [] }));
function failQuestion(question: SourceQuestion, error: string) {
	for (let repeat = 0; repeat < design.repeats; repeat++)
		for (const arm of arms)
			cells.push({
				questionId: question.id,
				packet: question.packet,
				suite: question.suite,
				repeat,
				arm,
				status: "failed",
				error,

				inputTokens: 0,
				outputTokens: 0,
				latencyMs: 0,
			});
}
checkpoint();
if (!values["prepare-only"]) {
	await withLuna(async (run) => {
		for (const packet of packets) {
			console.log(`Extract ${packet.id}`);
			let response: Awaited<ReturnType<typeof call>> | undefined;
			try {
				response = await call(
					`extract-${packet.id}`,
					extractionPrompt(packet),
					extractionSchema,
					run,
				);
				const material = interpret(packet, response.raw);
				const group: Prepared[] = [];
				for (const question of questions.filter(
					(q) => q.packet === packet.id,
				)) {
					const store = openTestStore();
					try {
						const history = store.write((db) =>
							persist(db, material, question.asOf),
						);
						const context = store.read((db) =>
							contexts(db, material, question),
						);
						group.push({ question, context: context.world, history });
					} finally {
						store.close();
					}
				}
				prepared.push(...group);
				extractionCosts.push({
					packetId: packet.id,
					status: "prepared",
					inputTokens: response.inputTokens,
					outputTokens: response.outputTokens,
					latencyMs: response.latencyMs,
				});
			} catch (e) {
				const error = String(e);
				extractionCosts.push({
					packetId: packet.id,
					status: "failed",
					error,
					...(response
						? {
								inputTokens: response.inputTokens,
								outputTokens: response.outputTokens,
								latencyMs: response.latencyMs,
							}
						: {}),
				});
				for (const q of questions.filter((q) => q.packet === packet.id))
					failQuestion(q, error);
			}
			checkpoint();
		}
	}, extractionInstructions);
	writeFileSync(
		resolve(output, "contexts.json"),
		JSON.stringify(prepared, null, 2),
	);
	const jobs = Array.from({ length: design.repeats }, (_, repeat) =>
		prepared.map((item, index) => ({ item, index, repeat })),
	).flat();
	// Reuse the existing isolated SDK lifecycle, with one instruction context per arm.
	async function withRunners(
		index: number,
		runners: Partial<Record<(typeof arms)[number], Run>>,
	): Promise<void> {
		const arm = arms[index];
		if (arm)
			return withLuna(
				(run) => withRunners(index + 1, { ...runners, [arm]: run }),
				instructions[arm],
			);
		let next = 0;
		async function worker() {
			while (next < jobs.length) {
				const { item, index, repeat } = jobs[next++]!;
				for (const arm of order(index, repeat)) {
					const base = {
						questionId: item.question.id,
						packet: item.question.packet,
						suite: item.question.suite,
						repeat,
						arm,
					};
					let response: Awaited<ReturnType<typeof call>> | undefined;
					try {
						response = await call(
							`answer-${item.question.id}-${repeat}-${arm}`,
							presentation(item.question, item.context),
							schemaFor(item.context, arm),
							runners[arm]!,
						);
						cells.push({
							...base,
							status: "answered",
							score: assess(item.question, item.context, arm, response.raw),
							inputTokens: response.inputTokens,
							outputTokens: response.outputTokens,
							latencyMs: response.latencyMs,
						});
					} catch (e) {
						cells.push({
							...base,
							status: "failed",
							error: String(e),
							inputTokens: response?.inputTokens ?? 0,
							outputTokens: response?.outputTokens ?? 0,
							latencyMs: response?.latencyMs ?? 0,
						});
					}
					report.status = "running";
					checkpoint();
					console.log(
						`${cells.length}/${design.plannedAnswers} ${item.question.id}/${repeat}/${arm}`,
					);
				}
			}
		}
		await Promise.all([worker(), worker()]);
	}
	await withRunners(0, {});
	report.codeUnchanged = codePaths.every(
		(f) => hash(readFileSync(resolve(root, f))) === digests[f],
	);
	report.status = !report.codeUnchanged
		? "invalidated-source-change"
		: cells.length !== design.plannedAnswers
			? "incomplete"
			: cells.some((c) => c.status === "failed")
				? "completed-with-failures"
				: "completed";
	checkpoint();
	if (report.status !== "completed") process.exitCode = 1;
}
console.log(
	JSON.stringify({
		status: report.status,
		newCalls,
		reused,
		report: resolve(output, "report.json"),
	}),
);

experimentSourceSnapshots.examples/instruction-order-factorial/pro:
import {
	answerInstructions,
	answerSchemaFor,
} from "../multi-source-comparison/protocol.ts";
import { instructions as previous } from "../applicability-order-comparison/protocol.ts";
import {
	answerPrompt,
	type AnswerContext,
} from "../multi-source-comparison/world.ts";
export const arms = ["baseline", "instruction", "order", "combined"] as const;
export type Arm = (typeof arms)[number];
export const factors = {
	baseline: { instruction: false, order: false },
	instruction: { instruction: true, order: false },
	order: { instruction: false, order: true },
	combined: { instruction: true, order: true },
} as const;
export const originalRecord = `Return a compact evidence record, not hidden reasoning: governingSources, assessments of the
operative permission rules, a brief explanation, then the final decision as the LAST field.`;
export const orderedRecord = `Return a compact evidence record, not hidden reasoning: assessments of the
operative permission rules, governingSources, a brief explanation, then the final decision as the LAST field.`;
// Recover the previous intervention verbatim, apart from removing its order-dependent connector.
const start = previous.applicability.indexOf(
	"Select permission rules by their authoritative provisions",
);
const middle = previous.applicability.indexOf(
	"Return a compact evidence record",
	start,
);
const coverageStart = previous.applicability.indexOf(
	"After writing assessments, include EVERY",
	middle,
);
const endText =
	"Check that no assessment source is missing from the completed source set.";
const end =
	previous.applicability.indexOf(endText, coverageStart) + endText.length;
if (
	start < 0 ||
	middle < start ||
	coverageStart < middle ||
	end < coverageStart ||
	!answerInstructions.includes(originalRecord)
)
	throw new Error("previous_intervention_changed");
export const selection = previous.applicability.slice(start, middle).trim();
export const coverage = previous.applicability
	.slice(coverageStart, end)
	.replace("After writing assessments, include EVERY", "Include EVERY");
export function instructionFor(arm: Arm) {
	const f = factors[arm];
	const record = f.order ? orderedRecord : originalRecord;
	return answerInstructions.replace(
		originalRecord,
		f.instruction ? `${selection}\n\n${record}\n${coverage}` : record,
	);
}
export const instructions = Object.fromEntries(
	arms.map((a) => [a, instructionFor(a)]),
) as Record<Arm, string>;
export const presentation = answerPrompt;
export function schemaFor(context: AnswerContext, arm: Arm) {
	const schema = answerSchemaFor(
		context.sources.map((s) => s.id),
		context.derivedView?.slice.units.map((u) => u.assertionId) ?? null,
	);
	if (!factors[arm].order) return schema;
	const { assessments, governingSources, explanation, decision } =
		schema.properties;
	const properties = { assessments, governingSources, explanation, decision };
	return { ...schema, properties, required: Object.keys(properties) };
}
// Four balanced Williams sequences: each arm occupies each position once and
// each ordered adjacent pair occurs once. Both cohorts are multiples of four.
const sequences: readonly (readonly Arm[])[] = [
	["baseline", "instruction", "combined", "order"],
	["instruction", "order", "baseline", "combined"],
	["order", "combined", "instruction", "baseline"],
	["combined", "baseline", "order", "instruction"],
];
export function order(index: number, repeat: number) {
	return sequences[(index + repeat * 2) % 4]!;
}
export const design = {
	repeats: 2,
	concurrency: 2,
	plannedExtractions: 4,
	plannedAnswers: 192,
	contrast:
		"2x2 factorial: exact v5; semantic instructions only; answer order only (text and schema order together); both. Semantic coverage is order-neutral. No new semantic rules beyond the previous bundle. Combined is normalized, not byte-identical to the prior candidate.",
	primary:
		"Exact decision, governing source set, permission assessment set/results and unchanged grounding audit. All first failures remain in planned denominators.",
	retention:
		"All calls complete; candidate all eight regression questions correct in both repeats; primary and decision counts nondecreasing versus v5 in each cohort; no false allow or retired-only source leak; unseen paired wins exceed losses overall AND in at least two new packets. No default promotion. Preserve previous experiment regardless.",
	attribution:
		"Report all four conditional contrasts, marginal primary-rate differences and difference-in-differences interaction separately by cohort. A factor has descriptive support only if neither conditional unseen contrast is negative, at least one positive, pooled conditional net is positive in at least two new packets, and its two treated arms do not lower decision counts or introduce false allow/retired leaks. Otherwise report mixed, ceiling or insufficient evidence, not a causal winner. Correlated repeats and authored fixtures preclude statistical generalization.",
	budget:
		"4 shared extractions plus 192 first answers; 120 seconds each, two workers. No application retries, repairs, fallback or resampling. Freeze before execution.",
	completion:
		"Partial and SQLite checks, verify/build, one live round, raw/explanation inspection, zero-call cache replay, reproducibility tests, saved decision and limitations, final verify/build, scope review, commit/push.",
};

